def find_project_dir():
    """Detects the SkillSwap 5.0 directory in Termux or current environment."""
    candidates = [
        os.getcwd(),
        os.path.expanduser("~/skillswap5.0"),
        "/data/data/com.termux/files/home/skillswap5.0",
        os.path.join(os.getcwd(), "skillswap5.0"),
        os.path.expanduser("~"),
    ]
    
    # Check if current directory is the project
    if os.path.exists("package.json") and (os.path.exists("src") or os.path.exists("server.ts")):
        return os.getcwd()
        
    for path in candidates:
        if os.path.isdir(path):
            pkg = os.path.join(path, "package.json")
            if os.path.exists(pkg):
                return path
                
    # If not found, default to ~/skillswap5.0
    default_path = os.path.expanduser("~/skillswap5.0")
    return default_path

def main():
    print("=" * 70)
    print("      SkillSwap 5.0 — Automated Termux Master Updater")
    print("=" * 70)
    
    if len(sys.argv) > 1:
        target_dir = os.path.abspath(sys.argv[1])
    else:
        target_dir = find_project_dir()
        
    print(f"[*] Target Project Directory: {target_dir}")
    
    if not os.path.exists(target_dir):
        print(f"[!] Directory '{target_dir}' does not exist. Creating it now...")
        os.makedirs(target_dir, exist_ok=True)
        
    # Create backup
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = os.path.join(target_dir, ".skillswap-backups", f"backup_{timestamp}")
    
    print(f"[*] Creating timestamped backup at: {backup_dir}")
    backed_up_count = 0
    
    written_count = 0
    updated_count = 0
    created_count = 0
    
    for rel_path, b64_data in FILES_PAYLOAD.items():
        dest_path = os.path.join(target_dir, rel_path)
        dest_dir = os.path.dirname(dest_path)
        
        # Decompress content
        raw_bytes = zlib.decompress(base64.b64decode(b64_data.encode('ascii')))
        
        # Backup if already exists
        if os.path.exists(dest_path):
            backup_path = os.path.join(backup_dir, rel_path)
            os.makedirs(os.path.dirname(backup_path), exist_ok=True)
            try:
                shutil.copy2(dest_path, backup_path)
                backed_up_count += 1
            except Exception as e:
                pass
            updated_count += 1
        else:
            created_count += 1
            
        os.makedirs(dest_dir, exist_ok=True)
        
        with open(dest_path, "wb") as f:
            f.write(raw_bytes)
            
        written_count += 1
        print(f"  [+] {'Updated' if os.path.exists(dest_path) else 'Created'}: {rel_path}")
        
    print("-" * 70)
    print(f"[SUCCESS] All changes applied successfully!")
    print(f"  - Total files written : {written_count}")
    print(f"  - Existing files updated: {updated_count}")
    print(f"  - New files created   : {created_count}")
    print(f"  - Backup created with : {backed_up_count} files")
    print("-" * 70)
    print("Next Steps in Termux:")
    print("  1. cd {target_dir}")
    print("  2. npm install")
    print("  3. npm run dev")
    print("=" * 70)

if __name__ == "__main__":
    main()
